const https = require('https');
const vars = $('Variaveis').first().json;
const usuario = $('Buscar Usuario').first().json.data;
const prompt = $('Montar Prompt').first().json;
const groqRes = $input.first().json;
const provedorIA = groqRes._provedor || 'desconhecido';
const tokensEntrada = groqRes._tokens_entrada ?? null;
const tokensSaida = groqRes._tokens_saida ?? null;

function httpReqBase(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const match = url.match(/^https?:\/\/([^/]+)(.*)/); const hostname = match[1]; const path = match[2] || '/';
    const opts = { hostname, path, method, headers: headers || {} };
    const req = https.request(opts, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { let corpo; try { corpo = JSON.parse(d); } catch(e) { corpo = { raw: d }; } resolve({ status: res.statusCode, corpo }); });
    });
    req.on('error', reject);
    if (body) req.write(typeof body === 'string' ? body : JSON.stringify(body));
    req.end();
  });
