      const recorrencias = (listaResp.ok && listaResp.data) ? listaResp.data : [];
      if (recorrencias.length > 0) {
        const cicloLabelMap = { semanal: msgs.cicloSemana, mensal: msgs.cicloMes, anual: msgs.cicloAno };
        const linhas = recorrencias.map(r => {
          const emoji = categoriaEmoji[r.categoria] || categoriaEmoji.outros;
          return '> ' + emoji + ' ' + r.descricao + ' — $' + Number(r.valor).toFixed(2) + '/' + cicloLabelMap[r.ciclo] + ' (desde ' + formataDataHora(r.data_inicio, true) + ')';
        }).join('\n');
        ia.resposta = '🔁 ' + msgs.recorrenciasTitulo + '\n\n' + linhas;
      } else {
        ia.resposta = msgs.semRecorrencias;
      }
    }

    if (ia.acao === 'extrato') {
      const agoraStr = new Date().toLocaleString('sv-SE', { timeZone: usuario.fuso_horario });
      let url = vars.BASE_URL + '/api/internal/transacao.php?id_usuario=' + usuario.id_usuario + '&por_pagina=30';
      let periodoLabel = null;
      if (ia.data_inicio) {
        const dataInicio = soData(ia.data_inicio);
        const dataFim = ia.data_fim ? soData(ia.data_fim) : dataInicio;
        url += '&data_inicio=' + encodeURIComponent(dataInicio) + '&data_fim=' + encodeURIComponent(dataFim);
        periodoLabel = dataInicio === dataFim ? formataDataHora(dataInicio, true) : formataDataHora(dataInicio, true) + ' a ' + formataDataHora(dataFim, true);
      } else {
        const mes = ia.mes ? Number(ia.mes) : Number(agoraStr.slice(5, 7));
        const ano = ia.ano ? Number(ia.ano) : Number(agoraStr.slice(0, 4));
        url += '&mes=' + mes + '&ano=' + ano;
      }
      if (ia.tipo_transacao === 'entrada' || ia.tipo_transacao === 'saida') url += '&tipo=' + ia.tipo_transacao;
      const data = await httpReq('GET', url, apiH);
      const transacoes = (data.ok && data.data && data.data.transacoes) ? data.data.transacoes : [];
      const resumo = (data.ok && data.data && data.data.resumo) ? data.data.resumo : null;
      if (transacoes.length > 0) {
        const linhas = transacoes.map(t => {
          const valor = Number(t.valor);
          const dataStr = formataDataHora(t.data_transacao, true);
          const sinal = t.tipo === 'entrada' ? '+' : '-';
          const emoji = categoriaEmoji[t.categoria] || categoriaEmoji.outros;
          return '> ' + emoji + ' ' + dataStr + ' ' + sinal + '$' + valor.toFixed(2) + ' \u2014 ' + t.descricao;
        }).join('\n');
        let saldoTexto;
        if (resumo) {
          const rotuloSaldo = periodoLabel ? msgs.saldoParcial : msgs.saldoMes;
          saldoTexto = '\ud83d\udcb0 ' + rotuloSaldo + ' $' + Number(resumo.saldo).toFixed(2) + ' (+$' + Number(resumo.total_entradas).toFixed(2) + ' / -$' + Number(resumo.total_saidas).toFixed(2) + ')';
        } else {
          let entradas = 0, saidas = 0;
          transacoes.forEach(t => { const v = Number(t.valor); if (t.tipo === 'entrada') entradas += v; else saidas += v; });
          saldoTexto = '\ud83d\udcb0 ' + msgs.saldoParcial + ' $' + (entradas - saidas).toFixed(2);
        }
        const tituloExtrato = '\ud83d\udcca ' + msgs.extrato + (periodoLabel ? ' (' + periodoLabel + ')' : '');
        ia.resposta = tituloExtrato + '\n\n' + linhas + '\n> ' + saldoTexto;
      } else {
        ia.resposta = msgs.semTransacoes;
      }
    }

    if (ia.acao === 'apagar_transacao') {
      const termo = normaliza(ia.titulo || ia.descricao || '');
      if (!termo || termo.length < 3) { ia.resposta = msgs.naoEncontradoTransacao; continue; }
      const data = await httpReq('GET', vars.BASE_URL + '/api/internal/transacao.php?id_usuario=' + usuario.id_usuario, apiH);
      const transacoes = (data.ok && data.data && data.data.transacoes) ? data.data.transacoes : [];
      const dataAlvo = ia.data_transacao ? soData(ia.data_transacao) : null;
      let candidatos = transacoes.filter(t => normaliza(t.descricao).includes(termo));
      if (dataAlvo) {
        const porData = candidatos.filter(t => soData(t.data_transacao) === dataAlvo);
        if (porData.length > 0) candidatos = porData;
      }

      if (candidatos.length === 0) {
        ia.resposta = msgs.naoEncontradoTransacao;
      } else if (candidatos.length > 1) {
        const nomes = candidatos.map(t => '"' + t.descricao + '" ($' + Number(t.valor).toFixed(2) + ', ' + soData(t.data_transacao) + ')').join(', ');
        ia.resposta = msgs.ambiguoTransacao + nomes;
      } else {
        const t = candidatos[0];
        await httpReq('DELETE', vars.BASE_URL + '/api/internal/transacao.php', apiH, JSON.stringify({ id_transacao: t.id_transacao }));
        const emojiCat = categoriaEmoji[t.categoria] || categoriaEmoji.outros;
        const sinalT = t.tipo === 'entrada' ? '+' : '-';
        ia.resposta = '🗑️ ' + msgs.removidoTransacao + '\n\n> ' + emojiCat + ' ' + t.descricao + '\n> 💰 ' + sinalT + '$' + Number(t.valor).toFixed(2) + '\n> 📅 ' + formataDataHora(t.data_transacao, true);
      }
    }
  }
} catch (e) {
  acoes[0].resposta = 'Erro: ' + e.message;
}

const respostaFinal = acoes.map(a => a.resposta).filter(r => r && r.trim()).join('\n\n') || 'Ok!';
const ultimaAcao = acoes[acoes.length - 1];

return [{
  json: {
    resposta: respostaFinal,
    acao: ultimaAcao.acao || 'conversa',
    id_usuario: usuario.id_usuario,
    contexto_novo: JSON.stringify({ ultima_acao: ultimaAcao.acao, ultimo_mensaje: prompt.user_message, ultima_resposta: respostaFinal, ultima_lista_titulos: ultimaListaTitulos }),
    _provedor: provedorIA,
    _tokens_entrada: tokensEntrada,
    _tokens_saida: tokensSaida
  }
}];
